const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'../..'),{UnifiedDataStore}=require(path.join(root,'out/db/unifiedDataStore.js')),{RuntimeDataExecutionDomains}=require(path.join(root,'out/runtimeDataExecutionDomains.js'));
const {writeStateNative}=require('./native-daily-state-oracles.cjs');
(async()=>{
  const base=fs.mkdtempSync(path.join(os.tmpdir(),'solomap-state-response-')),dataRoot=path.join(base,'data'),workspace=path.join(base,'project'),probe=path.join(base,'writer-json.jsonl');fs.mkdirSync(workspace);process.env.SOLOMAP_STATE_RESPONSE_PROBE=probe;
  const store=new UnifiedDataStore(dataRoot),project=await store.registerProject({root:workspace}),databaseId=store.databaseId,previousCoverage={version:1,provider:'c8-istanbul',status:'ready',generatedAt:'2026-11-16T00:00:00.000Z',lastAttemptAt:'2026-11-16T00:00:00.000Z',durationMs:1,testPassed:true,error:'',files:[],payload:'完整覆盖率原文🌿'.repeat(16000)},coverageSeed=writeStateNative(store,'analysis',project.projectId,{namespace:'coverage',key:'project-growth',expectedRevision:0,idempotencyKey:'coverage-seed',value:previousCoverage});store.close();const domains=await RuntimeDataExecutionDomains.start({root:dataRoot,databaseId}),results=[];let coverageText,externalId,externalFirst,externalNext,externalBytes;
  try{
    for(const type of ['analysis','strategy']){
      const operation=type==='analysis'?'write_analysis_state':'write_strategy_state',header={root:workspace,...(type==='analysis'?{namespace:'response',key:'complete'}:{})},firstValue={payload:'完整首版响应🌿'.repeat(16000),unknown:{retained:true}},nextValue={payload:'完整第二版响应🌿'.repeat(16000),unknown:{retained:'next'}},firstInput={...header,value:firstValue,expectedRevision:0,idempotencyKey:`first-${type}`};
      const firstText=await domains.dispatchSerialized({operation,input:firstInput}),first=JSON.parse(firstText);assert.deepEqual(first.value,firstValue);assert.equal(firstText,JSON.stringify(first));
      const nextText=await domains.dispatchSerialized({operation,input:{...header,value:nextValue,expectedRevision:1,idempotencyKey:`next-${type}`}}),next=JSON.parse(nextText);assert.equal(next.revision,2);assert.deepEqual(next.value,nextValue);assert.equal(nextText,JSON.stringify(next));
      const replay=await domains.dispatchSerialized({operation,input:{...firstInput,expectedSourceRevision:'ignored-after-commit',sourceProjectIds:['ignored-after-commit']}});assert.equal(replay,firstText);
      results.push({type,objectId:first.objectId,firstValue,nextValue,bytes:Buffer.byteLength(firstText),sha256:crypto.createHash('sha256').update(firstText).digest('hex')});
    }
    coverageText=await domains.dispatchSerialized({operation:'run_project_coverage_analysis',input:{root:workspace,extensionPath:root}});const coverage=JSON.parse(coverageText);assert.equal(coverage.status,'stale_failed');assert.equal(coverage.payload,previousCoverage.payload);assert.equal(coverageText,JSON.stringify(coverage));
    const externalHeader={root:workspace,key:'issues'},tokenA=JSON.parse(await domains.dispatchSerialized({operation:'reserve_external_refresh',input:{...externalHeader,requestId:'external-a'}})),cacheA={externalPayload:'完整外部首版响应🌿'.repeat(16000),unknown:{kept:true}},acceptedA=await domains.dispatchSerialized({operation:'commit_external_refresh',input:{...externalHeader,...tokenA,requestedAt:1,cache:cacheA}}),first=JSON.parse(acceptedA);assert.equal(first.accepted,true);assert.deepEqual(first.state.value.cache,cacheA);assert.equal(acceptedA,JSON.stringify(first));externalId=first.state.objectId;externalFirst=first.state.value;externalBytes=Buffer.byteLength(acceptedA);
    const tokenB=JSON.parse(await domains.dispatchSerialized({operation:'reserve_external_refresh',input:{...externalHeader,requestId:'external-b'}})),rejectedText=await domains.dispatchSerialized({operation:'commit_external_refresh',input:{...externalHeader,...tokenA,requestedAt:1,cache:{ignored:'旧代次'}}}),rejected=JSON.parse(rejectedText);assert.equal(rejected.accepted,false);assert.deepEqual(rejected.state,first.state);assert.equal(rejectedText,JSON.stringify(rejected));
    const cacheB={externalPayload:'完整外部第二版响应🌿'.repeat(16000),unknown:{kept:'next'}},acceptedB=await domains.dispatchSerialized({operation:'commit_external_refresh',input:{...externalHeader,...tokenB,requestedAt:2,cache:cacheB}}),next=JSON.parse(acceptedB);assert.equal(next.accepted,true);assert.equal(next.state.revision,2);assert.deepEqual(next.state.value.cache,cacheB);assert.equal(acceptedB,JSON.stringify(next));externalNext=next.state.value;
  }finally{await domains.close();}
  const read=UnifiedDataStore.openReadOnly(dataRoot,databaseId);
  try{
    for(const result of results){assert.equal(read.read(result.objectId,1).data.content,JSON.stringify(result.firstValue));assert.equal(read.read(result.objectId,2).data.content,JSON.stringify(result.nextValue));}
    assert.equal(read.read(coverageSeed.objectId,1).data.content,JSON.stringify(previousCoverage));const currentCoverage=read.readAnalysisState(project.projectId,'coverage','project-growth');assert.equal(currentCoverage.revision,2);assert.equal(JSON.stringify(currentCoverage.value),coverageText);
    assert.equal(read.read(externalId,1).data.content,JSON.stringify(externalFirst));assert.equal(read.read(externalId,2).data.content,JSON.stringify(externalNext));
    assert.equal(read.rows('SELECT COUNT(*) AS n FROM content_lifecycle_prepare_owners')[0].n,0);assert.equal(read.rows('SELECT COUNT(*) AS n FROM content_lifecycle_prepare_pins')[0].n,0);
  }finally{read.close();}
  const calls=fs.existsSync(probe)?fs.readFileSync(probe,'utf8').split('\n').filter(Boolean).map(line=>JSON.parse(line)):[];assert.deepEqual(calls,[],'actual Writer must consume the Compute current-state read and response encoding');process.stdout.write(JSON.stringify({sourceJsonCalls:calls,responses:12,coverageBytes:Buffer.byteLength(coverageText),externalBytes,results:results.map(({type,bytes,sha256})=>({type,bytes,sha256}))})+'\n');
})().catch(error=>{process.stderr.write(String(error.stack || error)+'\n');process.exitCode=1;});
